def drive(me, enemy, arena):
    b = bearing_to(enemy.x, enemy.y)
    d = distance_to(enemy.x, enemy.y)
    if me.inverted or me.on_side or not me.can_drive:
        return (0.0, 0.0)
    dead = True
    try:
        w = enemy.weapons.get("front")
        if w is not None and w.get("type") == "spinner" and w.get("health", 1) > 0.05:
            dead = False
    except Exception:
        dead = True
    mine_alive = True
    charged = False
    try:
        w = me.weapons.get("back")
        if w is None or w.get("health", 1) < 0.05:
            mine_alive = False
        else:
            charged = w.get("energy_j", 0) > 12000.0
    except Exception:
        mine_alive = False
    left = 0.0
    right = 0.0
    r = (me.x * me.x + me.y * me.y) ** 0.5
    cb = bearing_to(0.0, 0.0)
    if dead or not mine_alive:
        # enemy spinner gone (or mine gone): ram with the wedge, face the enemy
        if b > 25:
            left = 1.0
            right = 0.2
        elif b < -25:
            left = 0.2
            right = 1.0
        else:
            left = 1.0
            right = 1.0
    else:
        if charged and abs(b) > 110:
            # back rotor toward the enemy: drive backward at them
            bb = 180 - b if b > 0 else -180 - b
            if bb > 25:
                left = 1.0
                right = -0.3
            elif bb < -25:
                left = -0.3
                right = 1.0
            else:
                left = -1.0
                right = -1.0
        elif not charged and d < 1.8:
            # keep the wedge toward them, back off to charge
            if b > 25:
                left = -0.3
                right = -1.0
            elif b < -25:
                left = -1.0
                right = -0.3
            else:
                left = -0.6
                right = -0.6
        else:
            if b > 25:
                left = 1.0
                right = 0.2
            elif b < -25:
                left = 0.2
                right = 1.0
            else:
                left = 1.0
                right = 1.0
            if d < 0.9:
                left = left * 0.5
                right = right * 0.5
    if r > 5.2:
        # near the wall: turn and head back to the centre
        if cb > 15:
            left = left * 0.4 + 0.6
            right = right * 0.4 - 0.2
        elif cb < -15:
            left = left * 0.4 - 0.2
            right = right * 0.4 + 0.6
    return (left, right)

