def drive(me, enemy, arena):
    r = hypot(me.x, me.y)
    if r > 5.0:
        tx = 0.0
        ty = 0.0
    elif hypot(enemy.x, enemy.y) > 5.0:
        tx = 0.0
        ty = 0.0
    else:
        d = distance_to(enemy.x, enemy.y)
        if d > 1.8:
            hx = cos(radians(enemy.heading))
            hy = sin(radians(enemy.heading))
            perp_x = -hy
            perp_y = hx
            dx = me.x - enemy.x
            dy = me.y - enemy.y
            if dx * perp_x + dy * perp_y > 0:
                tx = enemy.x + perp_x * 0.5
                ty = enemy.y + perp_y * 0.5
            else:
                tx = enemy.x - perp_x * 0.5
                ty = enemy.y - perp_y * 0.5
        else:
            tx = enemy.x
            ty = enemy.y
    if r > 5.2 and abs(me.speed) < 0.2 and arena.time > 1.0:
        b = bearing_to(0.0, 0.0)
        if b > 10.0:
            return (-1.0, -0.5)
        elif b < -10.0:
            return (-0.5, -1.0)
        else:
            return (-1.0, -1.0)
    b = bearing_to(tx, ty)
    if b > 10.0:
        return (0.3, 1.0)
    elif b < -10.0:
        return (1.0, 0.3)
    else:
        return (1.0, 1.0)

