def drive(me, enemy, arena):
    r_me = hypot(me.x, me.y)
    r_enemy = hypot(enemy.x, enemy.y)
    d = distance_to(enemy.x, enemy.y)
    b = bearing_to(enemy.x, enemy.y)

    # If we are near the wall and not about to hit the enemy, steer back to center.
    if r_me > 5.0 and d > 1.5:
        b_center = bearing_to(0.0, 0.0)
        if b_center > 20.0:
            return (-0.5, 1.0)
        elif b_center < -20.0:
            return (1.0, -0.5)
        else:
            return (1.0, 1.0)

    # Target the enemy, but if the enemy is near the wall, aim slightly inside.
    if r_enemy > 5.0:
        vx = -enemy.x
        vy = -enemy.y
        n = hypot(vx, vy)
        if n > 0.01:
            tx = enemy.x + vx / n * 0.7
            ty = enemy.y + vy / n * 0.7
        else:
            tx = enemy.x
            ty = enemy.y
    else:
        tx = enemy.x
        ty = enemy.y

    b = bearing_to(tx, ty)
    if b > 30.0:
        return (-0.5, 1.0)
    elif b > 10.0:
        return (0.2, 1.0)
    elif b < -30.0:
        return (1.0, -0.5)
    elif b < -10.0:
        return (1.0, 0.2)
    else:
        return (1.0, 1.0)

def weapons(me, enemy, arena):
    w = me.weapons.get("front")
    if w is None or w.get("type") != "flipper":
        return None

    # Self-right if inverted and we have a working flipper with shots.
    if me.inverted and not me.righting:
        if w.get("health", 0.0) > 0.0 and w.get("shots_left", 0) > 0 and w.get("ready", False):
            return self_right()
        return None

    if me.righting or me.airborne or me.on_side:
        return None

    if not w.get("ready", False):
        return None
    if w.get("shots_left", 0) <= 0:
        return None
    if w.get("health", 0.0) <= 0.0:
        return None

    # Do not flip if the enemy is airborne, self-righting, or on its side.
    if enemy.airborne or enemy.righting or enemy.on_side:
        return None

    d = distance_to(enemy.x, enemy.y)
    b = bearing_to(enemy.x, enemy.y)

    # Flip if the enemy is close and roughly in front.
    if d < 1.5 and abs(b) < 35.0:
        return flip("front")

    return None
